// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp) public {
        uint256 blockNum = block.number;
        vm.assume(timestamp > c.pastBlockTime());
        uint256 initialBalance = address(c).balance;
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}(abi.encodeWithSignature(""));
        assertTrue(success);
        uint256 finalBalance = address(c).balance;
        if (blockNum % 15 == 0) {
            assertTrue(finalBalance == 0);
        } else {
            assertTrue(finalBalance > 0);
        }
    }
}

